/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, FracField, Mul, PolyRing, Pow, QQ, Sym, ZZ, add, exp, log, mul, pow, rational, sfield, symbols } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.fields", () => {
  it("((x**2 + y)/(z + 1)).diff(x)", () => {
    const [x, y, z] = symbols('x y z');
    const v1 = new FracField([x, y, z], ZZ, 'lex');
    const v2 = new FracField([x, y, z], ZZ, 'lex');
    expect(sympyStr(v1['new'](v1.ring.fromExpr(add(y, pow(x, 2))), v1.ring.fromExpr(add(1, z))).diff(v2['new'](v2.ring.fromExpr(x), v2.ring.fromExpr(rational(1)))))).toBe('2*x/(z + 1)');
  });
  it("K", () => {
    const x = new Sym('x');
    expect(sympyStr(at(sfield(mul(pow(x, rational(-5, 3)), add(mul(4, pow(x, 2)), mul(x, log(x))), exp(pow(x, -1)))), 0))).toBe('Rational function field in x, exp(1/x), log(x), x**(1/3) over ZZ with lex order');
  });
  it("f", () => {
    const x = new Sym('x');
    expect(sympyStr(at(sfield(mul(pow(x, rational(-5, 3)), add(mul(4, pow(x, 2)), mul(x, log(x))), exp(pow(x, -1)))), 1))).toBe('(4*x**2*(exp(1/x)) + x*(exp(1/x))*(log(x)))/((x**(1/3))**5)');
  });
});

